cards.solution:
type Dasar = { id: number };
type Barang = Dasar & { nama: string; stok: number };
const barang: Barang[] = [
  { id: 1, nama: "Gula", stok: 5 },
  { id: 2, nama: "Beras", stok: 0 },
  { id: 3, nama: "Kopi", stok: 9 },
];
for (const b of barang.filter((x) => x.stok > 0)) {
  console.log(`${b.id}:${b.nama}`);
}
